Rules.InvariantScript:
// Step 1: Filter the user's submissions
Set(
    lastUserSubmissions,
    Filter('Coverage Request (Belgium)', 'Created By'.Email = User().Email)
);

// Step 2: Find the highest ID among the user's submissions
Set(
    highestID,
    Max(lastUserSubmissions, ID)
);

// Step 3: Filter by the highest ID to get the last submission
Set(
    lastSubmission,
    LookUp(lastUserSubmissions, ID = highestID)
);

// Now `lastSubmission` contains the data of the last submitted request by the current user


// Step 4: Update the Commissioner input field with the last submission's Commissioner value
If(
    !IsBlank(lastSubmission),
    
    Set(ResetCheckboxes, true);
    Set(ResetCheckboxes, false);

    Set(varEventTypes, Blank());
    Set(otherEventValue, Blank());
    Set(VIPEventValue, Blank());

    Set(VideoCoverageSelected, false);
    Set(OnlyBilateralOtherVIPSelected, false);
    Set(varEventCoverageType, Blank());
    Set(varWebstreamed, Blank());
    Set(varWebstreamedOrganizer, Blank());
    Reset(CoverageTypeRadio);
    Reset(WebstreamedRadio);
    Reset(WebstreamedOrganizerText);

    Set(varCarbonCopyContactsString, Blank());
    Set(varCarbonCopyContactsArray, Blank());
    Set(varCarbonCopyContactsFormattedArray, Table());
    Reset(CarbonCopyContactComboBox);

    ResetForm(CoverageFormRequest);
    NewForm(CoverageFormRequest);

    Set(varCollegeMember, lastSubmission.'College Member');
    Set(varEventTitle, lastSubmission.'Event Title');

    Set(varStartDateTime, lastSubmission.'Start Date and Time');
    Set(varStartDate, DateValue(Text(varStartDateTime, "mm-dd-yyyy"), "en-US"));
   // Set(varStartHour, Text(If(Mod(Hour(varStartDateTime),12) = 0, 12, Mod(Hour(varStartDateTime), 12)), "[$-en-US]00"));
   // Set(varStartAMPM, If(Hour(varStartDateTime) <12, "[$-en-US]AM", "PM"));
    Set(varStartHour, Text(Hour(varStartDateTime), "[$-en-US]00")); 
    Set(varStartMinute, Text(Minute(varStartDateTime), "00"));

    Set(varEndDateTime, lastSubmission.'End Date and Time');
    Set(varEndDate, DateValue(Text(varEndDateTime, "mm-dd-yyyy"), "en-US"));
   // Set(varEndHour, Text(If(Mod(Hour(varEndDateTime),12) = 0, 12, Mod(Hour(varEndDateTime), 12)), "[$-en-US]00"));
   // Set(varEndAMPM, If(Hour(varEndDateTime) <12, "[$-en-US]AM", "PM"));
    Set(varEndHour, Text(Hour(varEndDateTime), "[$-en-US]00")); 
    Set(varEndMinute, Text(Minute(varEndDateTime), "00"));
   

    Set(varLocation, lastSubmission.Location);
    Set(varAddress, lastSubmission.Address);
    
    Set(varEventTypes, lastSubmission.'Event Type');

    Set(matchingOtherItem, First(Filter(varEventTypes, StartsWith(Value, "Other: "))));
    If(!IsBlank(matchingOtherItem),
        Set(otherEventValue, Mid(matchingOtherItem.Value, Len("Other :") + 1, Len(matchingOtherItem.Value))),
        Set(otherEventValue, "")
    );

    Set(matchingVIPItem, First(Filter(varEventTypes, StartsWith(Value, "VIP: "))));
    If(!IsBlank(matchingVIPItem),
        Set(VIPEventValue, Mid(matchingVIPItem.Value, Len("VIP:") + 1, Len(matchingVIPItem.Value))),
        Set(VIPEventValue, "")
    );
    
    Set(
    varEventTypes,
        ForAll(
            varEventTypes,
            Switch(
                true,
                StartsWith(Value, "Other: "), {Value: "Other"},
                StartsWith(Value, "VIP: "), {Value: "Bilateral with other VIP/s"},
                {Value: Value} // Default case
            )
        )
    );


    Set(TypeofEventSelected, EventTypeDropdown.SelectedItems.Value);

    Set(varCoverageTypes, lastSubmission.'Coverage Type');
    If("Video Coverage" in CoverageTypeDropdown.SelectedItems.Value, Set(VideoCoverageSelected, true));
    If("Bilateral with other VIP/s" in varEventTypes.Value && CountRows(varEventTypes) = 1, Set(OnlyBilateralOtherVIPSelected, true));
    Set(varEventCoverageType, lastSubmission.'Event Coverage Type');
    Set(varWebstreamed, lastSubmission.Webstreamed);
    Set(varWebstreamedOrganizer, lastSubmission.'Webstreamed Organizer');

    Set(varPublicationType, lastSubmission.'Publication Type');

    Set(varContacts, lastSubmission.'Accreditation Info');
    Set(varSocialMediaContacts, lastSubmission.'Media Receivers');
    Set(varTravelWithCommissionerContacts, lastSubmission.'Accompanying the Commissioner');
    Set(varCarbonCopyContactsString, lastSubmission.'Carbon Copy Contacts');
    Set(varCarbonCopyContactsArray, Split(Trim(lastSubmission.'Carbon Copy Contacts'), ";"));

    Set(
        varCarbonCopyContactsFormattedArray,
        ForAll(
            varCarbonCopyContactsArray,
            {
                DisplayName: ThisRecord.Value,
                Mail: TrimEnds(ThisRecord.Value)
            }
        )
    );

    Set(varComments, lastSubmission.Comments);

    Notify("The form has been filled with your last submission data " 
           & "[ID: " & lastSubmission.ID & "]  [Created on: " & Text(lastSubmission.Created, "dd/mm/yyyy hh:mm AM/PM", "en-GB") & "]", 
        NotificationType.Success)

)

Set(varCollegeMember, Blank());
Set(varEventTitle, Blank());
Set(varStartDate, Blank());
Set(varStartHour, Blank());
Set(varStartMinute, Blank());
Set(varEndDate, Blank());
Set(varEndHour, Blank());
Set(varEndMinute, Blank());
Set(varLocation, Blank());
Set(varAddress, Blank());
Set(varEventTypes, Blank());
Set(otherEventValue, Blank());
Set(VIPEventValue, Blank());
Set(varCoverageTypes, Blank());
Set(varPublicationType, Blank());
Set(varContacts, Blank());
Set(varComments, Blank());
Set(varSocialMediaContacts, Blank());
Set(varTravelWithCommissionerContacts, Blank());
Set(varCarbonCopyContactsString, Blank());
Set(varCarbonCopyContactsArray, Blank());
Set(varCarbonCopyContactsFormattedArray, Table());
Reset(CarbonCopyContactComboBox);

Set(checkFileds, false);
Set(VideoCoverageSelected, false);
Set(OnlyBilateralOtherVIPSelected, false);
Set(varEventCoverageType, Blank());
Set(varWebstreamed, Blank());
Set(varWebstreamedOrganizer, Blank());
Reset(CoverageTypeRadio);
Reset(WebstreamedRadio);
Reset(WebstreamedOrganizerText);

Set(TypeofEventSelected, Blank());

Set(ResetCheckboxes, true);
Set(ResetCheckboxes, false);

ResetForm(CoverageFormRequest); 
NewForm(CoverageFormRequest);

Notify( "The form has been cleared successfully", NotificationType.Information);

// Force fresh fetch from SharePoint, no cached version
Refresh(SuspensionDates);

// Get current date (no time)
Set(CurrentDate, Today());

// Calculate the minimum start date based on weekday and cutoff time
Set(
    ProposedStartDate,
    Switch(
        Weekday(CurrentDate, StartOfWeek.Monday),
        1, DateAdd(CurrentDate, 2),
        2, DateAdd(CurrentDate, 2),
        3, DateAdd(CurrentDate, 2),
        4, DateAdd(CurrentDate, 2),
        5, If(Hour(Now()) < 17, DateAdd(CurrentDate, 2), DateAdd(CurrentDate, 4)),
        6, DateAdd(CurrentDate, 3),
        7, DateAdd(CurrentDate, 2)
    )
);

// Apply the floor: never earlier than 04/06/2025
Set(
    MinStartDate,
    If(
        ProposedStartDate <= Date(2025, 6, 3),
        Date(2025, 6, 4),
        ProposedStartDate
    )
);

// Block the suspension window
With(
    {
        matchedSuspension: First(
            Filter(
                SuspensionDates,
                Active,
                StartDatePicker.SelectedDate >= StartBlockedDate,
                StartDatePicker.SelectedDate <= EndBlockedDate
            )
        )
    },
    If(
        !IsBlank(matchedSuspension),
        Notify(
            "⚠ Start date " & Text(StartDatePicker.SelectedDate, "[$-en-GB]dd/mm/yyyy") &
            " is not available. Reason: " & matchedSuspension.Title &
            " (" & Text(matchedSuspension.StartBlockedDate, "[$-en-GB]dd/mm/yyyy") &
            " to " & Text(matchedSuspension.EndBlockedDate, "[$-en-GB]dd/mm/yyyy") & "). " &
            "Please pick a date from " &
            Text(DateAdd(matchedSuspension.EndBlockedDate, 1), "[$-en-GB]dddd dd/mm/yyyy") & " onwards.",
            NotificationType.Warning,
            8000
        )
    )
)

With(
    {
        totalMinutes: DateDiff(
            DateTimeValue(
                Text(StartDatePicker.SelectedDate, "yyyy-mm-dd") & " " & 
                Text(Value(StartHour.Selected.Value), "[$-en-US]00") & ":" & 
                StartMinute.Selected.Value
            ),
            DateTimeValue(
                Text(EndDatePicker.SelectedDate, "yyyy-mm-dd") & " " & 
                Text(Value(EndHour.Selected.Value), "[$-en-US]00") & ":" & 
                EndMinute.Selected.Value
            ),
            TimeUnit.Minutes
        )
    },
    If(
        totalMinutes > 0,
        Text(
            Int(totalMinutes / 1440) & " days, " & Char(10) &
            Int(Mod(totalMinutes, 1440) / 60) & " hours, " & Char(10) &
            Mod(totalMinutes, 60) & " minutes"
        ),
        "Incorrect duration"
    )
)

If(LocationRadio.Selected.Value = "Berlaymont Building" && Or(!IsBlank(varTravelWithCommissionerContacts), !IsBlank(Trim(TravelWithCommissionerContactsInput.Text))), 
    Set(varTravelWithCommissionerContacts, Blank());
    Reset(TravelWithCommissionerContactsInput);
    
    Set(varContacts, Blank());
    Reset(AccreditationInfoInput);
    
    Notify("'Who will be accompanying the Commissioner' and 'Contacts and Detailed Info for Accreditation' REMOVED", NotificationType.Warning);
)

Set(varEventTypes, ShowColumns( Filter(EventTypeGallery.AllItems, EventTypeOption.Value),Value));

If("Bilateral with Minister or other VIP/s" in varEventTypes.Value && CountRows(varEventTypes) = 1, 
    Set(OnlyBilateralOtherVIPSelected, true);
    Set(varCoverageTypes, Filter(varCoverageTypes, Value <> "Video Coverage"));

    Set(VideoCoverageSelected, false);

    Set(varEventCoverageType, Blank()); 
    Reset(CoverageTypeRadio);

    Set(varWebstreamed, Blank());
    Reset(WebstreamedRadio);

    Set(varWebstreamedOrganizer, Blank());
    Reset(WebstreamedOrganizerText);
    
    Notify("'Video Coverage' option REMOVED", NotificationType.Warning);
    ,
    Set(OnlyBilateralOtherVIPSelected, false)
);

Set(varEventTypes, ShowColumns( Filter(EventTypeGallery.AllItems, EventTypeOption.Value),Value));

If("Bilateral with Minister or other VIP/s" in varEventTypes.Value && CountRows(varEventTypes) = 1, 
    Set(OnlyBilateralOtherVIPSelected, true);
    Set(varCoverageTypes, Filter(varCoverageTypes, Value <> "Video Coverage"));

    Set(VideoCoverageSelected, false);

    Set(varEventCoverageType, Blank()); 
    Reset(CoverageTypeRadio);

    Set(varWebstreamed, Blank());
    Reset(WebstreamedRadio);

    Set(varWebstreamedOrganizer, Blank());
    Reset(WebstreamedOrganizerText);
    
    Notify("'Video Coverage' option REMOVED", NotificationType.Warning);
    ,
    Set(OnlyBilateralOtherVIPSelected, false);
);


If(EventTypeOption.Text = "Bilateral with other VIP/s",
    Set(VIPEventValue, Blank());
);


If(EventTypeOption.Text = "Other",
    Set(otherEventValue, Blank());
);

Set(varCoverageTypes, ShowColumns( Filter(CoverageTypeGallery.AllItems, CoverageTypeCheckBox.Value), Value));

If(CoverageTypeCheckBox.Text = "Video Coverage", 
    Set(varWebstreamedOrganizer, Blank());
    Reset(WebstreamedOrganizerText);

    Set(varEventCoverageType, Blank()); 
    Reset(CoverageTypeRadio);

    Set(varWebstreamed, Blank());
    Reset(WebstreamedRadio);    
);

Set(varSocialMediaContacts, 
    Trim(
        Trim(SocialMediaContactsInput.Text)
        & Char(13)
        & "Name: " & SearchSocialMediaContacts.Selected.DisplayName & ", "
        & "Email: " & SearchSocialMediaContacts.Selected.Mail)
    );

Reset(SearchSocialMediaContacts);

Set(varCarbonCopyContactsString, Concat(CarbonCopyContactComboBox.SelectedItems, Mail & "; " & Char(13)));

// Force fresh fetch from SharePoint, no cached version
Refresh(SuspensionDates);

// Step 1: Refresh the suspension data from SharePoint
Refresh(SuspensionDates);

// Get Current Date (no Time)
Set(CurrentDate, Today());

Set(
    MinStartDate,
    If(
        Switch(
            Weekday(CurrentDate, StartOfWeek.Monday),
            1, DateAdd(CurrentDate, 2),
            2, DateAdd(CurrentDate, 2),
            3, DateAdd(CurrentDate, 2),
            4, DateAdd(CurrentDate, 2),
            5, If(TimeValue(Text(Now(), "hh:mm:ss")) < TimeValue("17:00:00"), DateAdd(CurrentDate, 2), DateAdd(CurrentDate, 4)),
            6, DateAdd(CurrentDate, 3),
            7, DateAdd(CurrentDate, 2)
        ) <= DateValue("2025-06-03"),
        DateValue("2025-06-04"),
        Switch(
            Weekday(CurrentDate, StartOfWeek.Monday),
            1, DateAdd(CurrentDate, 2),
            2, DateAdd(CurrentDate, 2),
            3, DateAdd(CurrentDate, 2),
            4, DateAdd(CurrentDate, 2),
            5, If(TimeValue(Text(Now(), "hh:mm:ss")) < TimeValue("17:00:00"), DateAdd(CurrentDate, 2), DateAdd(CurrentDate, 4)),
            6, DateAdd(CurrentDate, 3),
            7, DateAdd(CurrentDate, 2)
        )
    )
);


If
  (	
	StartDatePicker.SelectedDate < MinStartDate 
    || 'Start Date Data Card'.Update >= 'End Date Data Card'.Update,

    Notify("Please fix the errors", NotificationType.Error),
    
    If(CoverageFormRequest.Valid 
        && (!("Other" in varEventTypes.Value) || ("Other" in varEventTypes.Value && !IsBlank(Trim(OtherEventTypeInput.Text))))
        && (!("Bilateral with other VIP/s" in varEventTypes.Value) || ("Bilateral with other VIP/s" in varEventTypes.Value && !IsBlank(Trim(VIPNameFunctionInput.Text)))),
        
        Set(
            varEventTypes,
            ForAll(
                varEventTypes,
                Switch(
                    Value,
                    "Other", {Value: "Other: " & Trim(OtherEventTypeInput.Text)},
                    "Bilateral with other VIP/s", {Value: "VIP: " & Trim(VIPNameFunctionInput.Text)},
                    {Value: Value} // Default case
                )
            )
        );

    // Step 2: After refresh, check if the button is still in Edit mode (enabled)
If(
    Button3.DisplayMode = DisplayMode.Edit,
    SubmitForm(CoverageFormRequest),
     // Button is disabled -> block submission and notify
    Notify(
        "Your request cannot be submitted. The selected dates are no longer valid, possibly due to a recently added suspension period. Please refresh the app and try again.",
        NotificationType.Error,
        8000
    )
);

        Set(varCollegeMember, Blank());
        Set(varEventTitle, Blank());
        Set(varStartDate, Blank());
        Set(varStartHour, Blank());
        Set(varStartMinute, Blank());
        Set(varEndDate, Blank());
        Set(varEndHour, Blank());
        Set(varEndMinute, Blank());
        Set(varLocation, Blank());
        Set(varAddress, Blank());
        Set(varEventTypes, Blank());
        Set(otherEventValue, Blank());
        Set(VIPEventValue, Blank());
        Set(varCoverageTypes, Blank());
        Set(varPublicationType, Blank());
        Set(varContacts, Blank());
        Set(varComments, Blank());
        Set(varSocialMediaContacts, Blank());
        Set(varTravelWithCommissionerContacts, Blank());

        Set(checkFileds, false);
        Set(VideoCoverageSelected, false);
        Set(OnlyBilateralOtherVIPSelected, false);
        Set(varEventCoverageType, Blank());
        Set(varWebstreamed, Blank());
        Set(varWebstreamedOrganizer, Blank());
        Reset(CoverageTypeRadio);
        Reset(WebstreamedRadio);
        Reset(WebstreamedOrganizerText);

        Set(TypeofEventSelected, Blank());

        Set(ResetCheckboxes, true);
        Set(ResetCheckboxes, false);
    
        , 

        Set(checkFileds, true);
        Notify( "Please fill in all required fields ", NotificationType.Error);
        
    ); 
);
